package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_deserialize_TriageGen1Test {

    private StringArrayDeserializer deserializer;

    @Mock
    private JsonParser jp;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private ObjectBuffer buffer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        deserializer = new StringArrayDeserializer();

        // Setup buffer behavior
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        when(buffer.resetAndStart()).thenReturn(new Object[2]);
        when(buffer.appendCompletedChunk(any())).thenReturn(new Object[4]);
        when(buffer.completeAndClearBuffer(any(), anyInt(), eq(String.class))).thenAnswer(invocation -> {
            Object[] chunk = invocation.getArgument(0);
            int len = invocation.getArgument(1);
            String[] result = new String[len];
            for (int i = 0; i < len; i++) {
                result[i] = (String) chunk[i];
            }
            return result;
        });
    }

    @Test
    public void testDeserialize_NonArrayToken() throws IOException {
        // Testing the branch: if (!jp.isExpectedStartArrayToken())
        when(jp.isExpectedStartArrayToken()).thenReturn(false);

        // Since handleNonArray is protected/private and we can't easily mock it 
        // without a spy, we rely on the fact that it's called.
        // We need to spy the deserializer to verify the call if we want to be precise,
        // but here we just ensure it doesn't crash and follows the branch.
        StringArrayDeserializer spyDeserializer = spy(deserializer);

        spyDeserializer.deserialize(jp, ctxt);

        verify(spyDeserializer).deserialize(jp, ctxt); 
        // In a real scenario, handleNonArray would be tested via its own logic or integration.
    }

    @Test
    public void testDeserialize_CustomDeserializerPresent() throws IOException {
        // Testing the branch: if (_elementDeserializer != null)
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        setPrivateField(deserializer, "_elementDeserializer", mock(com.fasterxml.jackson.databind.JsonDeserializer.class));

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        setPrivateField(spyDeserializer, "_elementDeserializer", deserializer.getClass().getDeclaredField("_elementDeserializer").get(deserializer)); // dummy setup

        // Mocking _deserializeCustom call via spy
        doReturn(new String[]{"custom"}).when(spyDeserializer)._deserializeCustom(jp, ctxt);

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"custom"}, result);
        verify(spyDeserializer)._deserializeCustom(jp, ctxt);
    }

    @Test
    public void testDeserialize_StandardArrayWithStringsAndNulls() throws IOException {
        // Testing the main logic: VALUE_STRING, VALUE_NULL, and buffer chunking
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        // Sequence: START_ARRAY (already checked), "a", null, "b", "c" (to trigger chunking)
        // Chunk size is 2 (set in setUp)
        when(jp.nextToken())
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.VALUE_NULL)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("a", "b", "c");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"a", null, "b", "c"}, result);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserialize_ParseStringBranch() throws IOException {
        // Testing the branch: else { value = _parseString(jp, ctxt); }
        // This triggers when token is not STRING or NULL (e.g., NUMBER or BOOLEAN)
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        when(jp.nextToken())
            .thenReturn(JsonToken.VALUE_NUMBER_INT)
            .thenReturn(JsonToken.END_ARRAY);

        // We need to mock the internal _parseString. Since it's protected, 
        // we use a spy to override it.
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn("123").when(spyDeserializer)._parseString(jp, ctxt);

        // Manually trigger the logic by calling the spy
        // Note: _parseString is part of the class, so we must ensure the spy uses it.
        // However, the actual deserialize method is being tested.

        // Because _parseString is protected, we can't mock it easily without a spy 
        // but the code is actually calling it. Let's use a spy to intercept.
        // We must use the spy for the call.

        // Re-setup for spy
        when(jp.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT, JsonToken.END_ARRAY);

        // Since we can't easily mock _parseString without changing the object, 
        // let's assume it's a standard Jackson behavior or we use a subclass.
        // For this test, we'll assume the logic goes into the 'else' branch.

        // Since I cannot change the source code, I will use a subclass to override _parseString
        StringArrayDeserializer testDeserializer = new StringArrayDeserializer() {
            @Override
            protected String _parseString(JsonParser jp, DeserializationContext ctxt) throws IOException {
                return "parsed";
            }
        };

        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(jp.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT, JsonToken.END_ARRAY);

        String[] result = testDeserializer.deserialize(jp, ctxt);
        assertArrayEquals(new String[]{"parsed"}, result);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
